<?php
 namespace QQWorld\Setup\Console\Command; use QQWorld\Setup\Model\AdminAccount; use QQWorld\Framework\Setup\ConsoleLogger; use QQWorld\Setup\Model\InstallerFactory; use QQWorld\User\Model\UserValidationRules; use Symfony\Component\Console\Input\InputOption; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface; class AdminUserCreateCommand extends AbstractSetupCommand { private $installerFactory; private $validationRules; public function __construct(InstallerFactory $installerFactory, UserValidationRules $validationRules) { $this->installerFactory = $installerFactory; $this->validationRules = $validationRules; parent::__construct(); } protected function configure() { $this->setName('admin:user:create') ->setDescription('Creates an administrator') ->setDefinition($this->getOptionsList()); parent::configure(); } protected function execute(InputInterface $input, OutputInterface $output) { $errors = $this->validate($input); if ($errors) { $output->writeln('<error>' . implode('</error>' . PHP_EOL . '<error>', $errors) . '</error>'); return \QQWorld\Framework\Console\Cli::RETURN_FAILURE; } $installer = $this->installerFactory->create(new ConsoleLogger($output)); $installer->installAdminUser($input->getOptions()); $output->writeln( '<info>Created QQWorld administrator user named ' . $input->getOption(AdminAccount::KEY_USER) . '</info>' ); } public function getOptionsList() { return [ new InputOption(AdminAccount::KEY_USER, null, InputOption::VALUE_REQUIRED, '(Required) Admin user'), new InputOption(AdminAccount::KEY_PASSWORD, null, InputOption::VALUE_REQUIRED, '(Required) Admin password'), new InputOption(AdminAccount::KEY_EMAIL, null, InputOption::VALUE_REQUIRED, '(Required) Admin email'), new InputOption( AdminAccount::KEY_FIRST_NAME, null, InputOption::VALUE_REQUIRED, '(Required) Admin first name' ), new InputOption( AdminAccount::KEY_LAST_NAME, null, InputOption::VALUE_REQUIRED, '(Required) Admin last name' ), ]; } public function validate(InputInterface $input) { $errors = []; $user = new \QQWorld\Framework\DataObject(); $user->setFirstname($input->getOption(AdminAccount::KEY_FIRST_NAME)) ->setLastname($input->getOption(AdminAccount::KEY_LAST_NAME)) ->setUsername($input->getOption(AdminAccount::KEY_USER)) ->setEmail($input->getOption(AdminAccount::KEY_EMAIL)) ->setPassword( $input->getOption(AdminAccount::KEY_PASSWORD) === null ? '' : $input->getOption(AdminAccount::KEY_PASSWORD) ); $validator = new \QQWorld\Framework\Validator\DataObject; $this->validationRules->addUserInfoRules($validator); $this->validationRules->addPasswordRules($validator); if (!$validator->isValid($user)) { $errors = array_merge($errors, $validator->getMessages()); } return $errors; } } 